def ball(G, S, k):
    current = set(S)
    for _ in range(k):
        current |= {w for v in current for w in G.adj[v]}
    return current

def quotient(G, f, m):
    edges = set()
    for u in range(G.n):
        for v in G.adj[u]:
            edges.add((f[u], f[v]))
    return DiGraph(m, list(edges))

def entropy_profile(G, v, n):
